Definition cell_kn (c : Z * nat * Z) : kentry :=
  match c with (a, w, v) => KWord (SA (ELit 0) a) w (ELit v) end.
Definition kn_cells (cs : list (Z * nat * Z)) : list kentry := map cell_kn cs.

